variables.alerts:
{%- set ns = namespace(a=[]) -%}
{%- set h0 = now().strftime('%Y-%m-%dT%H:00:00') -%}
{%- set h3 = (now() + timedelta(hours=3)).strftime('%Y-%m-%dT%H:00:00') -%}
{%- set h12 = (now() + timedelta(hours=12)).strftime('%Y-%m-%dT%H:00:00') -%}
{%- set h18 = (now() + timedelta(hours=18)).strftime('%Y-%m-%dT%H:00:00') -%}
{%- set soon = hourly | selectattr('datetime', '>=', h0) | selectattr('datetime', '<=', h3) | list -%}
{%- set storm = soon | selectattr('condition', 'in', ['lightning', 'lightning-rainy']) | list -%}
{%- if storm -%}
  {%- set t = as_datetime(storm[0].datetime).strftime('%-I%p') | lower -%}
  {%- set ns.a = ns.a + [{'key': 'thunder', 'severe': true, 'title': 'Thunderstorms on the way',
       'message': 'Storms forecast ' ~ ('now' if storm[0].datetime == h0 else 'from about ' ~ t) ~ '. Bring things in and keep an eye on the radar.'}] -%}
{%- endif -%}
{%- set day = hourly | selectattr('datetime', '>=', h0) | selectattr('datetime', '<=', h12) | list -%}
{%- set gusts = day | map(attribute='wind_gust_speed') | select('number') | list -%}
{%- if gusts and gusts | max >= 60 -%}
  {%- set peak = day | selectattr('wind_gust_speed', 'eq', gusts | max) | first -%}
  {%- set ns.a = ns.a + [{'key': 'wind', 'severe': gusts | max >= 80, 'title': 'Strong winds',
       'message': 'Gusts up to ' ~ (gusts | max | round) ~ ' km/h around ' ~ (as_datetime(peak.datetime).strftime('%-I%p') | lower) ~ '.'}] -%}
{%- endif -%}
{%- set today = daily | selectattr('datetime', 'search', now().strftime('%Y-%m-%d')) | first | default(none) -%}
{%- if today and today.temperature is number and today.temperature >= 33 and now().hour < 17 -%}
  {%- set ns.a = ns.a + [{'key': 'heat', 'severe': today.temperature >= 40, 'title': 'Hot day',
       'message': 'Up to ' ~ (today.temperature | round) ~ '° today. Close the blinds early and keep the heat pump ready.'}] -%}
{%- endif -%}
{%- set night = hourly | selectattr('datetime', '>=', h0) | selectattr('datetime', '<=', h18) | list -%}
{%- set temps = night | map(attribute='temperature') | select('number') | list -%}
{%- if temps and temps | min <= 3 and now().hour >= 12 -%}
  {%- set low = night | selectattr('temperature', 'eq', temps | min) | first -%}
  {%- set ns.a = ns.a + [{'key': 'cold', 'severe': false, 'title': 'Cold night',
       'message': 'Down to ' ~ (temps | min | round) ~ '° around ' ~ (as_datetime(low.datetime).strftime('%-I%p') | lower) ~ '. Frost is possible.'}] -%}
{%- endif -%}
{%- set m = minutely or [] -%}
{%- if m and m[0].precipIntensity < 0.1 -%}
  {%- set wet = m | selectattr('precipIntensity', '>=', 0.3) | selectattr('precipProbability', '>=', 0.5) | list -%}
  {%- if wet -%}
    {%- set mins = ((wet[0].time - now().timestamp()) / 60) | round | int -%}
    {%- set ns.a = ns.a + [{'key': 'rain', 'severe': false, 'title': 'Rain soon',
         'message': 'Rain starting ' ~ ('in the next few minutes' if mins < 5 else 'in about ' ~ mins ~ ' min') ~ ' (' ~ (wet[0].time | timestamp_custom('%-I:%M%p') | lower) ~ ').'}] -%}
  {%- endif -%}
{%- endif -%}
{{ ns.a }}
